export function encryptBytes(key: CryptoKey, bytes: Uint8Array): Promise<string>;
export function decryptBytes(key: CryptoKey, text: string): Promise<Uint8Array>;
export function encryptJson(key: CryptoKey, obj: unknown): Promise<string>;
export function decryptJson<T = any>(key: CryptoKey, text: string): Promise<T>;
